# Frozen-reference regression test for the smcfcs.cycle() refactor
# (design/smcfcs-cycle.md, section 4.2). The references were generated by
# data-raw/make-references.R on the baseline commit. Each case is rerun
# from its stored inputs and must give identical() results.
#
# Exactness depends on the environment (R version, RNG, BLAS/LAPACK and
# the versions of the packages smcfcs calls), so a case is skipped, not
# failed, when the environment differs from the one that made it. This is
# also why the test is skipped on CRAN.

ref_files <- list.files(test_path("reference"), pattern = "\\.rds$",
                        full.names = TRUE)

test_that("reference files are present", {
  skip_on_cran()
  expect_gt(length(ref_files), 0)
})

env_now <- reference_environment()

for (f in ref_files) {
  ref <- readRDS(f)
  test_that(paste("identical to reference:", ref$case$name), {
    skip_on_cran()
    env_ref <- ref$environment
    for (what in c("R", "platform", "RNGkind", "BLAS", "LAPACK")) {
      if (!identical(env_ref[[what]], env_now[[what]])) {
        skip(paste0(what, " differs from the reference (",
                    paste(env_ref[[what]], collapse = " "), ")"))
      }
    }
    pk <- names(env_ref$packages)
    diff <- pk[!mapply(identical, env_ref$packages[pk], env_now$packages[pk])]
    if (length(diff) > 0) {
      skip(paste("package version differs from the reference:",
                 paste(diff, collapse = ", ")))
    }

    res <- run_reference_case(ref$case)
    expect_identical(res$impDatasets, ref$result$impDatasets)
    expect_identical(res$smCoefIter, ref$result$smCoefIter)
    expect_identical(res$smInfo, ref$result$smInfo)
    expect_identical(res$warnings, ref$result$warnings)
  })
}
